"use client";
import React, { useEffect, useRef, useState } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import { cn } from "@/lib/utils";

export interface TimelineItem {
  id: string;
  label: string;
  content?: React.ReactNode;
}

interface TimelineProps {
  items?: TimelineItem[];
  title?: string;
  description?: string;
  containerClass?: string;
  className?: string;
}

export function Timeline({
  items = [],
  title,
  description,
  containerClass,
  className,
}: TimelineProps) {
  const timelineRef = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState(0);

  useEffect(() => {
    if (timelineRef.current) {
      const rect = timelineRef.current.getBoundingClientRect();
      setHeight(rect.height);
    }
  }, []);

  const { scrollYProgress } = useScroll({
    target: timelineRef,
    offset: ["start 10%", "end 50%"],
  });

  const opacityTransform = useTransform(scrollYProgress, [0, 0.1], [0, 1]);
  const heightTransform = useTransform(scrollYProgress, [0, 1], [0, height]);

  return (
    <div className={cn("w-full bg-white font-sans md:px-10 dark:bg-neutral-950", containerClass)}>
      <div className="mx-auto max-w-7xl px-4 py-20 md:px-8 lg:px-10">
        {title && (
          <h2 className="mb-4 max-w-4xl text-lg text-black md:text-4xl dark:text-white">
            {title}
          </h2>
        )}
        {description && (
          <p className="max-w-sm text-sm text-neutral-700 md:text-base dark:text-neutral-300">
            {description}
          </p>
        )}
      </div>

      <div ref={timelineRef} className={cn("relative z-0 mx-auto max-w-7xl pb-20", className)}>
        {items.map((item, index) => (
          <div
            key={item.id + index}
            className="flex justify-start pt-10 md:gap-10 md:pt-40"
          >
            <div className="sticky top-40 z-40 flex max-w-xs flex-col items-center self-start md:w-full md:flex-row lg:max-w-sm">
              <div className="absolute left-3 flex size-10 items-center justify-center rounded-full bg-white md:left-3 dark:bg-black">
                <div className="size-4 rounded-full border border-neutral-300 bg-neutral-200 p-2 dark:border-neutral-700 dark:bg-neutral-800" />
              </div>
              <h3 className="hidden text-xl font-bold text-neutral-500 md:block md:pl-20 md:text-5xl dark:text-neutral-500">
                {item.label}
              </h3>
            </div>
            <div className="relative w-full pl-20 pr-4 md:pl-4">
              {item.content}
            </div>
          </div>
        ))}

        <div
          style={{ height: `${height}px` }}
          className="absolute top-0 left-8 w-[2px] overflow-hidden bg-[linear-gradient(to_bottom,var(--tw-gradient-stops))] from-transparent from-0% via-neutral-200 to-transparent to-99% [mask-image:linear-gradient(to_bottom,transparent_0%,black_10%,black_90%,transparent_100%)] md:left-8 dark:via-neutral-700"
        >
          <motion.div
            style={{
              height: heightTransform,
              opacity: opacityTransform,
            }}
            className="absolute inset-x-0 top-0 w-[2px] rounded-full bg-gradient-to-t from-purple-500 from-0% via-blue-500 via-10% to-transparent"
          />
        </div>
      </div>
    </div>
  );
}
